// v23.xx (gfx8), HIS ORDER (2026-10-12) on the graphics program: "add ALL of this stuff", item 2, shadows that follow light. LAMP
// COOKIES. Under LIGHTING HIGH every lamp's light is cut by the walls around it: a lamp throws its pool only where it can see, so a
// wall between a lamp and the floor leaves that floor in its shadow, and light pours through doorways and window gaps (windows
// never stop light, as they never stop sight). Each lamp's sight polygon is cast once from the wall segments within its reach
// (96 rays plus two either side of every corner), and the light is baked through it into two soft sprites (the light map stamp and
// the colour pool) at half a pixel per unit, 15 percent of the light left outside the polygon as bounce so roofs and the backs of
// walls are never black. LIFT-AWARE: walls are drawn standing up to 26 units above their collider (HIS #45, the wall lift band),
// so a ray that meets a wall's south face from the south carries on by the wall's lift, and the front face you can see is lit
// while the floor behind the wall stays dark. A broken wall or an opened door rebuilds the segments, and a cookie baked against
// the old segments is baked again. At most 2 bakes a frame (the rest draw the plain STANDARD pool until their turn), one more
// lamp prebaked on any frame with budget left, so a raid's lamps are all baked within about a second. At most 96 cookies are kept,
// oldest dropped first, in the store registry (a lost context empties it). A flickering lamp under HIGH flickers in strength,
// not in size, so its shadows stay on the walls. STANDARD draws the colour without shadows; CLASSIC is unchanged.
var LCOOK=gfxStore('lcook',function(s){ s.order=[]; s.done=null; });
LCOOK.order=[]; LCOOK.bakes=0; LCOOK.cap=96; LCOOK.budget=0; LCOOK.scan=0; LCOOK.done=null;
function gfxCookieKey(L){ return Math.round(L.x)+','+Math.round(L.y)+','+Math.round(L.r)+','+L.c+','+L.i; }
// the drawn lift of the wall whose south face a segment is (the 26 above the collider rule, v9.27), 0 for trees and ledges
function gfxFaceLift(s,nw){
  var i, w, mx=(s.x1+s.x2)/2;
  for(i=0;i<nw.length;i++){
    w=nw[i];
    if(Math.abs(w.y+w.h-s.y1)>.01||mx<w.x||mx>w.x+w.w) continue;
    if(w.win||w.tree||w.ledge) return 0;
    return w.lift||((w.w<=60&&w.h<=60)?14:26);
  }
  return 0;
}
function gfxLampPoly(L){
  var r=L.r, segs=(G.map&&G.map.segs)||[], walls=(G.map&&G.map.walls)||[], near=segsNear(L.x,L.y,r,segs), nw=[], A=[], poly=[],
      i, j, s, a, an, dx, dy, best, bs, sx, sy, den, qx, qy, t, u, w, lift;
  for(i=0;i<walls.length;i++){ w=walls[i]; if(w.x>L.x+r||w.x+w.w<L.x-r||w.y>L.y+r||w.y+w.h<L.y-r) continue; nw.push(w); }
  for(i=0;i<96;i++) A.push(-Math.PI+i/96*6.283185);
  for(i=0;i<near.length;i++){
    s=near[i];
    a=Math.atan2(s.y1-L.y,s.x1-L.x); A.push(a-.0009,a+.0009);
    a=Math.atan2(s.y2-L.y,s.x2-L.x); A.push(a-.0009,a+.0009);
  }
  A.sort(function(m,n){ return m-n; });
  for(j=0;j<A.length;j++){
    an=A[j]; dx=Math.cos(an); dy=Math.sin(an); best=r; bs=null;
    for(i=0;i<near.length;i++){
      s=near[i]; sx=s.x2-s.x1; sy=s.y2-s.y1; den=dx*sy-dy*sx;
      if(den>-1e-9&&den<1e-9) continue;
      qx=s.x1-L.x; qy=s.y1-L.y; t=(qx*sy-qy*sx)/den;
      if(t<0||t>=best) continue;
      u=(qx*dy-qy*dx)/den;
      if(u<0||u>1) continue;
      best=t; bs=s;
    }
    t=best;
    // a south face met from the south: its front face stands lift units up the screen, so the light carries on over it
    if(bs&&dy<-.2&&bs.y1===bs.y2&&bs.x1>bs.x2){ lift=gfxFaceLift(bs,nw); if(lift>0) t=Math.min(r,best+lift/(-dy)); }
    poly.push(L.x+dx*t,L.y+dy*t);
  }
  return poly;
}
function gfxCookieBake(L,poly,kind,R){
  var k=.5, S=Math.ceil(2*R*k)+2, c=document.createElement('canvas'), x, spr=gfxLightSpr(L.c,kind), i;
  c.width=S; c.height=S; x=c.getContext('2d');
  x.setTransform(k,0,0,k,S/2-L.x*k,S/2-L.y*k);
  x.globalAlpha=.15; x.drawImage(spr,L.x-R,L.y-R,R*2,R*2);   // the bounce
  x.save();
  x.beginPath(); x.moveTo(poly[0],poly[1]);
  for(i=2;i<poly.length;i+=2) x.lineTo(poly[i],poly[i+1]);
  x.closePath(); x.clip();
  x.globalAlpha=.85; x.drawImage(spr,L.x-R,L.y-R,R*2,R*2);
  x.restore();
  return {c:c,h:S/k/2};
}
function gfxCookie(L,bake){
  var segs=G&&G.map&&G.map.segs, key, e, poly, old;
  if(!segs) return null;
  key=gfxCookieKey(L); e=LCOOK.m[key];
  if(e&&e.segs===segs) return e;
  if(!bake||!(LCOOK.budget>0)) return null;
  LCOOK.budget--;
  poly=gfxLampPoly(L);
  if(!e){ LCOOK.n++; LCOOK.order.push(key); }
  e={key:key,segs:segs,pts:poly.length/2,map:gfxCookieBake(L,poly,'map',L.r),glow:gfxCookieBake(L,poly,'glow',L.r*.5)};
  LCOOK.m[key]=e; LCOOK.bakes++;
  while(LCOOK.n>LCOOK.cap&&LCOOK.order.length){ old=LCOOK.order.shift(); if(LCOOK.m[old]){ delete LCOOK.m[old]; LCOOK.n--; } }
  return e;
}
// one more lamp of the raid baked ahead of time on a frame with budget left, so walking into a new street does not wait for them
function gfxCookiePrebake(){
  var n=G.lights.length, segs=G.map&&G.map.segs, k, L, e;
  if(!n||!segs||!(LCOOK.budget>0)||(LCOOK.done===segs&&LCOOK.doneN===n)) return;
  for(k=0;k<n;k++){
    LCOOK.scan=(LCOOK.scan+1)%n; L=G.lights[LCOOK.scan]; e=LCOOK.m[gfxCookieKey(L)];
    if(!e&&LCOOK.n>=LCOOK.cap) continue;   // a full store is never churned ahead of time; lamps in view still bake as they appear
    if(!e||e.segs!==segs){ gfxCookie(L,true); return; }
  }
  LCOOK.done=segs; LCOOK.doneN=n;
}
function gfxLightFail(e){

var hi=(((typeof gfxLightNow==='function')?gfxLightNow():CFG.gfxLight)!==1), ck;   // v23.xx (gfx8): HIGH casts the lamps through their cookies; STANDARD (and the quality ladder's rung 3) draws the plain pools
LCOOK.budget=hi?2:0;
if(!LMAP.c){ LMAP.c=document.createElement('canvas'); LMAP.x=LMAP.c.getContext('2d'); }

ck=hi?gfxCookie(L,false):null;   // v23.xx (gfx8): the pool through the same cookie as the light
if(ck) wc.drawImage(ck.glow.c,gx-ck.glow.h,gy-ck.glow.h,ck.glow.h*2,ck.glow.h*2);
else wc.drawImage(gfxLightSpr(L.c,'glow'),gx-gr,gy-gr,gr*2,gr*2);

