{v:'VER',what:'graphics program gfx8: lamp cookies with lift-aware shadows: a lamp south of a wall lights the floor in front of it but the floor behind the wall keeps at most a quarter of the light STANDARD gives it under LIGHTING HIGH, the wall front face (10 units inside the collider, the lifted face) keeps at least 80 percent, open floor the other side of the lamp keeps at least 80 percent, at most 96 cookies are kept, and rebuilding the wall segments bakes the cookie again',
 run:function(){
   if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)||typeof render2D!=='function'||typeof rebuildGeometry!=='function') return 'SKIP: this fixture cannot stage and draw a raid frame';
   if(typeof LCOOK==='undefined'||typeof LMAP==='undefined'||typeof gfxCookieKey!=='function') return 'no LCOOK: lamps cast no shadows';
   var bad=[], g=null, p, gl0=CFG.gfxLight, L0=null, E0=null, F0=null, W=null, ws, i, k, w, cx, Ly, Qy, Fy, Oy, lamp, amb, s1, h1, e0, e1, key, segs0;
   function inWall(x,y,skip){ for(var q=0;q<ws.length;q++){ var v=ws[q]; if(v===skip) continue; if(x>=v.x-3&&x<=v.x+v.w+3&&y>=v.y-3&&y<=v.y+v.h+3) return true; } return false; }
   function mapAt(wx,wy){
     var Zq=ZOOM()*SOFTR, mx=Math.round((wx-VX)*Zq), my=Math.round((wy-VY)*Zq), d, m, s=0, n=0;
     if(mx<2||my<2||mx>LMAP.c.width-3||my>LMAP.c.height-3) return null;
     d=LMAP.x.getImageData(mx-1,my-1,3,3).data;
     for(m=0;m<d.length;m+=4){ s+=d[m+1]; n++; }
     return s/n-amb;
   }
   function read(q){ CFG.gfxLight=q; for(var f=0;f<4;f++) __frame(0.12); return [mapAt(cx,Qy),mapAt(cx,Fy),mapAt(cx,Oy)]; }
   try{
     __resetCfg();
     g=__gfxStage({cond:'night',wx:'clear',frames:3});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(isDay()) return 'SKIP: the staged raid is not at night';
     p=g.player; G.shake=0; G.lightning=0;
     ws=G.map.walls;
     // a plain wall near him, open floor 25 south of it and 35 north of it, nothing else between
     for(i=0;i<ws.length&&!W;i++){
       w=ws[i];
       if(w.tree||w.furn||w.wreck||w.ruin||w.win||w.door||w.ledge||w.lockWall||!(w.lift>=14)||w.w<80||w.h>40) continue;
       cx=w.x+w.w/2; Ly=w.y+w.h+25; Qy=w.y-35; Fy=w.y+w.h-10; Oy=Ly+(Ly-Qy);
       if(Qy<60||Oy>WORLD_H-60||cx<300||cx>WORLD_W-300) continue;
       if(inWall(cx,Ly,null)||inWall(cx,Qy,null)||inWall(cx,Oy,null)) continue;
       var clear=true; for(k=Qy;k<=Oy;k+=4){ if(k>=w.y-3&&k<=w.y+w.h+3) continue; if(inWall(cx,k,w)){ clear=false; break; } }
       if(!clear) continue;
       W=w;
     }
     if(!W) return 'SKIP: staging: no plain wall with open floor both sides near the start';
     L0=G.lights; E0=G.ents; F0=G.flashes; G.ents=[]; G.flashes=[];
     lamp={x:cx,y:Ly,r:200,c:'#ffffff',i:.5,f:0,fl:false};
     G.lights=[lamp];
     p.x=cx+320; p.y=Ly; G.anchX=undefined;
     amb=Math.round(255*(1-clamp(NIGHT_SHEET/(CFG.bright||1),.05,.82)));
     s1=read(1); h1=read(2);
     if(!s1[0]||!s1[1]||!s1[2]||!h1) return 'SKIP: staging: the wall left the screen';
     if(!(s1[0]>=6)) return 'SKIP: staging: STANDARD gives the floor behind the wall only '+s1[0];
     if(h1[0]===null||h1[0]>0.25*s1[0]) bad.push('behind the wall the floor keeps '+h1[0]+' of the '+s1[0]+' light STANDARD gives it (want a quarter or less)');
     if(h1[1]===null||h1[1]<0.8*s1[1]) bad.push('the lifted front face of the wall keeps '+h1[1]+' of '+s1[1]+' (want 80 percent or more)');
     if(h1[2]===null||h1[2]<0.8*s1[2]) bad.push('open floor on the lamp side keeps '+h1[2]+' of '+s1[2]+' (want 80 percent or more)');
     if(!(LCOOK.n<=96)) bad.push(LCOOK.n+' cookies kept (cap 96)');
     key=gfxCookieKey(lamp); e0=LCOOK.m[key]; segs0=G.map.segs;
     if(!e0) bad.push('no cookie was baked for the lamp');
     rebuildGeometry();
     for(k=0;k<3;k++) __frame(0);
     e1=LCOOK.m[key];
     if(G.map.segs===segs0) bad.push('rebuildGeometry kept the segment list');
     else if(!e1||e1===e0||e1.segs!==G.map.segs) bad.push('the cookie was not baked again against the rebuilt walls');
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     CFG.gfxLight=gl0;
     try{ if(g&&G===g){ if(L0) G.lights=L0; if(E0) G.ents=E0; if(F0) G.flashes=F0; } }catch(_r){}
     try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){}
     __topClear(); __cleanProfile();
   }
   return bad.length?bad.join('; '):null; }},
